function P.noclipOff()
    local c = lp.Character
    if not c then return end
    for _, n in ipairs({ "Head", "Torso", "UpperTorso", "LowerTorso", "HumanoidRootPart" }) do
        local p = c:FindFirstChild(n)
        if p then p.CanCollide = true end
    end
end
function P.moveOff()
    local h = M.hum()
    if h then
        if not on("p_speed") and S.walk0 then h.WalkSpeed = S.walk0 S.walk0 = nil end
        if not on("p_jump") then h.JumpPower = 50 end
    end
end
P.PLACES = { "Home", "Adoption Center", "Furniture Store", "Clothing Store", "Hospital" }
function P.tp(name)
    local map = { ["Adoption Center"] = "AdoptionCenter", ["Furniture Store"] = "FurnitureStore", ["Clothing Store"] = "PetStore", ["Hospital"] = "VetHospital" }
    local target
    if name == "Home" then
        local plot = M.plot()
        target = plot and plot.House:FindFirstChild("SpawnPoint")
    else
        local m = Workspace:FindFirstChild(map[name] or "")
        target = m and (m:FindFirstChild("Arrival", true) or m)
    end
    local s = target and M.near(M.posOf(target))
    if s then M.go(s) else notify(__T["Not available right now"]) end
end
function P.hop()
    task.spawn(function()
        local ok, data = pcall(function()
            return HttpService:JSONDecode(game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&excludeFullGames=true&limit=100"))
        end)
        if ok and type(data) == "table" and data.data then
            local pool = {}
            for _, s in ipairs(data.data) do if s.id ~= game.JobId and s.playing and s.playing < s.maxPlayers then pool[#pool + 1] = s.id end end
            if #pool > 0 then
                TeleportService:TeleportToPlaceInstance(game.PlaceId, pool[math.random(1, #pool)], lp)
                return
            end
        end
        notify(__T["No other server found"])
    end)
end
